// `next dev` writes route types to .next/dev/types, which tsconfig includes. When a page is
// removed (e.g. /dev/books in step 5), those stale types break `tsc` and `next build`.
// They are regenerated by the next `next dev`, so it is safe to drop them first.
import { rmSync } from "node:fs";

rmSync(new URL("../.next/dev/types", import.meta.url), { recursive: true, force: true });
